a.equal(m.parseDf(""),null); a.equal(m.parseDf("df: /nope: No such file"),null); a.ok(!m.isLow(null,10));
a.equal(m.parseDf("h\n10 5 /mnt/my disk\n").mount,"/mnt/my disk");
